with.setup:
tee /etc/nginx/nginx.conf <<EOF
daemon off;
user root;

events {
    worker_connections 1024;
}

http {
  server {
    listen       8080 default_server;
    listen       [::]:8080 default_server;
    server_name  _;
    root         /usr/share/nginx/html;
    location /hello {
      add_header Content-Type text/html;

      return 200 "Hello, Linky!";
    }
    location /redirect {
      return 301 /hello;
    }
  }
}
EOF

nginx -t
